120	  .sliders { display: grid; grid-template-columns: auto 1fr auto; gap: 8px 12px; align-items: center; margin-top: 16px; font-size: 14px; }
121	  .sliders output { color: var(--muted); min-width: 48px; text-align: right; font-variant-numeric: tabular-nums; }
122	  input[type=range] { width: 100%; accent-color: var(--accent); }
123	
124	  .custom { display: flex; gap: 8px; margin-top: 12px; }
