133	  .stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-bottom: 16px; }
134	  .stat { background: var(--bg); border-radius: 8px; padding: 8px 10px; }
135	  .stat b { display: block; font-size: 20px; font-variant-numeric: tabular-nums; }
136	  .stat small { color: var(--muted); font-size: 12px; }
137	
138	  pre.code {
139	    margin: 0;
140	    font: 13px/1.7 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
141	    background: var(--bg);
142	    border-radius: 8px;
143	    padding: 8px 0;
144	    overflow-x: auto;
145	  }
146	  pre.code div { padding: 0 12px; border-left: 3px solid transparent; white-space: pre; }
147	  pre.code div.hl { background: var(--code-hl); border-left-color: var(--compare); }
148	
