const results = [];
function runCase(vals) {
  document.getElementById('customInput').value = vals.join(', ');
  document.getElementById('apply').click();
  const last = steps[steps.length - 1];
  const byId = new Map(items.map(it => [it.id, it.v]));
  const finalVals = last.order.map(id => byId.get(id));
  const expected = vals.slice().sort((a,b)=>a-b);
  // 逐步点击“下一步”直到结束，检查高亮行与控制台
  let clicks = 0;
  while (!document.getElementById('next').disabled) { document.getElementById('next').click(); clicks++; }
  const hlLines = [...document.querySelectorAll('#code .ln.hl .no')].map(e => e.textContent);
  return {
    vals: vals.join(','),
    sortedOk: JSON.stringify(finalVals) === JSON.stringify(expected),
    steps: steps.length, clicks,
    output: document.getElementById('console').textContent,
    hlAtEnd: hlLines,
    mainLine: document.querySelectorAll('#code .ln')[20].textContent,
    stats: [statPass.textContent, statCmp.textContent, statSwp.textContent].join('/'),
  };
}
results.push(runCase([5,3,8,1,9,2]));
results.push(runCase([1,2,3,4,5]));
results.push(runCase([9,8,7,6,5,4,3,2,1]));
for (let k = 0; k < 50; k++) {
  const n = 2 + Math.floor(Math.random()*29);
